  if(($_FILES[$field]['size']??0)>5*1024*1024)throw new RuntimeException('Görsel boyutu 5 MB sınırını aşamaz.');
  $dir=dirname(__DIR__).'/uploads/'.$folder;if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('Yükleme klasörü oluşturulamadı.');
  $name=bin2hex(random_bytes(14)).'.'.$allowed[$mime];if(!move_uploaded_file($tmp,$dir.'/'.$name))throw new RuntimeException('Görsel yüklenemedi.');return 'uploads/'.$folder.'/'.$name;
}
